import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVAT, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';
import { TIER_DISCOUNTS } from '../src/customers.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 }
    ]
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2024-01-15');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);

  // First line
  assert.equal(r.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r.value.lines[0].name, 'Design work (hour)');
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].unitPrice, 8500);
  assert.equal(r.value.lines[0].vatRate, 21);

  // Second line
  assert.equal(r.value.lines[1].sku, 'STICKER');
  assert.equal(r.value.lines[1].name, 'Sticker sheet');
  assert.equal(r.value.lines[1].qty, 100);
  assert.equal(r.value.lines[1].unitPrice, 50);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }]
  });

  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice returns DATE_INVALID for non-date issueDate', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: 'not-a-date',
      lines: [{ sku: 'DES-HOUR', qty: 1 }]
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice returns DATE_INVALID for invalid dates', () => {
  const invalidDates = [
    '2024-02-30',  // February doesn't have 30 days
    '2024-13-01',  // No month 13
    '2024-01-32',  // January doesn't have 32 days
    '2024/01/15',  // Wrong separator
    '01-15-2024',  // Wrong order
    '2024-1-15',   // Missing leading zero on month
    ''
  ];

  for (const date of invalidDates) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }]
    });
    assert.equal(r.ok, false, `Should reject date: ${date}`);
    assert.equal(r.error, 'DATE_INVALID', `Should be DATE_INVALID for: ${date}`);
  }
});

test('createInvoice accepts valid leap year dates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-29',
    lines: [{ sku: 'DES-HOUR', qty: 1 }]
  });

  assert.equal(r.ok, true);
  assert.equal(r.value.issueDate, '2024-02-29');
});

test('createInvoice returns NO_LINES for empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: []
  });

  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns NO_LINES for missing lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15'
  });

  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice returns QTY_INVALID for non-integer qty', () => {
  const invalidQtys = [0, -1, 1.5, 'hello', null, undefined];

  for (const qty of invalidQtys) {
    const r = createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DES-HOUR', qty }]
    });
    assert.equal(r.ok, false, `Should reject qty: ${qty}`);
    assert.equal(r.error, 'QTY_INVALID', `Should be QTY_INVALID for: ${qty}`);
  }
});

test('createInvoice returns UNKNOWN_SKU for unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }]
  });

  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLine = { ...lines[0] };

  createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines
  });

  assert.deepEqual(lines[0], originalLine);
  assert.equal(lines[0].name, undefined);
  assert.equal(lines[0].unitPrice, undefined);
});

test('createInvoice returns different line objects than catalogue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  // Modify the returned line
  r.value.lines[0].qty = 999;

  // Create another invoice and verify it's not affected
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  assert.equal(r2.value.lines[0].qty, 5);
});

test('lineTotal calculates qty × unitPrice in cents', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 50 }), 5000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal handles qty of 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
});

test('lineTotal handles large quantities', () => {
  assert.equal(lineTotal({ qty: 10000, unitPrice: 1000 }), 10000000);
});

test('invoiceTotals calculates subtotal as sum of line totals', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'STICKER', qty: 100, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21%: 8925
  // STICKER: 100 * 50 = 5000, VAT 21%: 1050
  // Subtotal: 47500, VAT: 9975, Total: 57475
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9975);
  assert.equal(totals.total, 57475);
});

test('invoiceTotals includes VAT in total with no discounts', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 10 * 8500 = 85000, VAT 21%: 17850
  // DEV-HOUR: 8 * 9500 = 76000, VAT 21%: 15960
  // Subtotal: 161000, VAT: 33810, Total: 194810
  assert.equal(totals.subtotal, 161000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 33810);
  assert.equal(totals.total, 194810);
});

test('invoiceTotals works with single line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'LOGO-PACK', qty: 1, discountPercent: 0 }]
  });

  const totals = invoiceTotals(r.value);
  // LOGO-PACK: 1 * 120000 = 120000, VAT 21%: 25200
  // Total: 145200
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 25200);
  assert.equal(totals.total, 145200);
});

test('invoiceTotals works with many lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'SUPPORT-HOUR', qty: 2, discountPercent: 0 },
      { sku: 'STICKER', qty: 50, discountPercent: 0 }
    ]
  });

  const totals = invoiceTotals(r.value);
  // DES-HOUR: 5 * 8500 = 42500, VAT 21%: 8925
  // DEV-HOUR: 3 * 9500 = 28500, VAT 21%: 5985
  // SUPPORT-HOUR: 2 * 7250 = 14500, VAT 21%: 3045
  // STICKER: 50 * 50 = 2500, VAT 21%: 525
  // Subtotal: 88000, VAT: 18480, Total: 106480
  assert.equal(totals.subtotal, 88000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 18480);
  assert.equal(totals.total, 106480);
});

test('addLine adds a new line to an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const r2 = addLine(r.value, { sku: 'STICKER', qty: 100 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'STICKER');
  assert.equal(r2.value.lines[1].qty, 100);
  assert.equal(r2.value.lines[1].name, 'Sticker sheet');
  assert.equal(r2.value.lines[1].unitPrice, 50);
});

test('addLine increases qty if SKU already exists', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
  assert.equal(r2.value.lines[0].qty, 8);
});

test('addLine validates qty like createInvoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const invalidQtys = [0, -1, 1.5, 'hello', null, undefined];
  for (const qty of invalidQtys) {
    const r2 = addLine(r.value, { sku: 'STICKER', qty });
    assert.equal(r2.ok, false, `Should reject qty: ${qty}`);
    assert.equal(r2.error, 'QTY_INVALID', `Should be QTY_INVALID for: ${qty}`);
  }
});

test('addLine returns UNKNOWN_SKU for unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const r2 = addLine(r.value, { sku: 'NOPE', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine returns NOT_DRAFT if invoice is not in draft status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const notDraft = { ...r.value, status: 'sent' };
  const r2 = addLine(notDraft, { sku: 'STICKER', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const originalLength = r.value.lines.length;
  addLine(r.value, { sku: 'STICKER', qty: 100 });
  assert.equal(r.value.lines.length, originalLength);
  assert.equal(r.value.lines[0].qty, 5);
});

test('addLine can add multiple times', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  let invoice = r.value;
  invoice = addLine(invoice, { sku: 'STICKER', qty: 100 }).value;
  invoice = addLine(invoice, { sku: 'ICON-SET', qty: 10 }).value;

  assert.equal(invoice.lines.length, 3);
  assert.equal(invoice.lines[1].sku, 'STICKER');
  assert.equal(invoice.lines[2].sku, 'ICON-SET');
});

test('removeLine removes a line from an invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 }
    ]
  });

  const r2 = removeLine(r.value, 'STICKER');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'DES-HOUR');
});

test('removeLine returns LINE_NOT_FOUND if SKU is not on invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const r2 = removeLine(r.value, 'NOPE');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine returns NO_LINES if it would remove the last line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  const r2 = removeLine(r.value, 'DES-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine returns NOT_DRAFT if invoice is not in draft status', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 }
    ]
  });

  const notDraft = { ...r.value, status: 'sent' };
  const r2 = removeLine(notDraft, 'STICKER');
  assert.deepEqual(r2, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 }
    ]
  });

  const originalLength = r.value.lines.length;
  removeLine(r.value, 'STICKER');
  assert.equal(r.value.lines.length, originalLength);
});

test('removeLine can remove multiple times', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'STICKER', qty: 100 },
      { sku: 'ICON-SET', qty: 10 }
    ]
  });

  let invoice = r.value;
  invoice = removeLine(invoice, 'ICON-SET').value;
  invoice = removeLine(invoice, 'STICKER').value;

  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
});

test('addLine and removeLine work together', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }]
  });

  let invoice = r.value;
  invoice = addLine(invoice, { sku: 'STICKER', qty: 100 }).value;
