  assert.equal(r2.ok, true);

  const r3 = applyVoucher(r2.value, { code: 'SAVE20', amount: 10000 });
  assert.deepEqual(r3, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher returns AMOUNT_INVALID for zero amount', () => {
