  });

  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: -1000 });
  assert.deepEqual(r2, { ok: false, error: 'AMOUNT_INVALID' });
});

test('applyVoucher returns AMOUNT_INVALID for non-integer amount', () => {
