test('applyVoucher can be removed by creating new invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(r2.value.voucher.amount, 5000);

  // Create new invoice without voucher
  const r3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  assert.equal(r3.value.voucher, undefined);
});

test('applyVoucher with large amount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }]
  });

  // Total: 51425
  const r2 = applyVoucher(r.value, { code: 'BIGDISCOUNT', amount: 60000 });
  assert.equal(r2.ok, true);

  // Total should be clamped at 0: max(0, 51425 - 60000) = 0
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.total, 0);
});

test('applyVoucher preserves all invoice data', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'STICKER', qty: 100 }
    ],
    terms: 'NET14'
  });

  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });

  // Check all original data is preserved
  assert.equal(r2.value.customerId, 'C-002');
  assert.equal(r2.value.issueDate, '2024-01-15');
  assert.equal(r2.value.status, 'draft');
  assert.equal(r2.value.terms, 'NET14');
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.voucher.code, 'SAVE10');
  assert.equal(r2.value.voucher.amount, 5000);
});

test('applyVoucher with line discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }]
  });

  // Subtotal: 42500
  // Line discount (10%): 4250
  // VAT (21% on 42500 - 4250 = 38250): 8032.5 -> 8032 (rounded)
  // Total before voucher: 42500 - 4250 + 8032 = 46282

  const totals1 = invoiceTotals(r.value);
  assert.equal(totals1.subtotal, 42500);
  assert.equal(totals1.discount, 4250);
  assert.equal(totals1.vat, 8032);
  assert.equal(totals1.total, 46282);

  // Apply 5000 voucher
  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  const totals2 = invoiceTotals(r2.value);
  assert.equal(totals2.voucher, 5000);
  // Total: 46282 - 5000 = 41282
  assert.equal(totals2.total, 41282);
});

